import shlex
import re


def handle(query, state):
    logfile = (query.get("logfile") or ["/var/log/app.log"])[0]
    lines_param = (query.get("lines") or ["10"])[0]
    try:
        n_lines = max(1, int(lines_param))
    except ValueError:
        n_lines = 10

    files = state.get("files", {})
    log_files = state.get("log_files", [])

    def _expand_arith(s):
        def _eval(m):
            try:
                return str(eval(m.group(1), {"__builtins__": {}}, {}))
            except Exception:
                return m.group(0)
        return re.sub(r"\$\(\(([^)]+)\)\)", _eval, s)

    def _run_cmd(cmd_str):
        cmd_str = cmd_str.strip()
        if not cmd_str:
            return ""
        try:
            parts = shlex.split(cmd_str)
        except ValueError:
            return "[parse error]"
        if not parts:
            return ""
        prog = parts[0]
        args = [_expand_arith(a) for a in parts[1:]]

        if prog == "cat":
            path = args[0] if args else ""
            content = files.get(path)
            if content is None:
                return f"cat: {path}: No such file or directory"
            return content
        elif prog == "tail":
            n = n_lines
            path = None
            i = 0
            while i < len(args):
                if args[i] == "-n" and i + 1 < len(args):
                    try:
                        n = int(args[i + 1])
                    except ValueError:
                        pass
                    i += 2
                else:
                    if path is None:
                        path = args[i]
                    i += 1
            if path is None:
                return "tail: missing operand"
            if log_files and path not in log_files:
                return f"tail: {path}: Permission denied"
            content = files.get(path)
            if content is None:
                return f"tail: {path}: No such file or directory"
            tail_lines = content.splitlines()
            return "\n".join(tail_lines[-n:])
        elif prog == "echo":
            return " ".join(args)
        elif prog == "ls":
            path = args[0] if args else "/"
            entries = set()
            for fp in files:
                if fp.startswith(path.rstrip("/") + "/"):
                    remainder = fp[len(path.rstrip("/")) + 1:]
                    top = remainder.split("/")[0]
                    entries.add(top)
            return "\n".join(sorted(entries)) if entries else ""
        else:
            return f"{prog}: command not found"

    def _eval_pipeline(pipeline_str):
        segments = []
        current = []
        in_sq = False
        in_dq = False
        for ch in pipeline_str:
            if ch == "'" and not in_dq:
                in_sq = not in_sq
                current.append(ch)
            elif ch == '"' and not in_sq:
                in_dq = not in_dq
                current.append(ch)
            elif ch == ";" and not in_sq and not in_dq:
                segments.append("".join(current))
                current = []
            else:
                current.append(ch)
        segments.append("".join(current))
        outputs = []
        for seg in segments:
            out = _run_cmd(seg)
            if out:
                outputs.append(out)
        return "\n".join(outputs)

    cmd = f"tail -n {n_lines} {logfile}"
    output = _eval_pipeline(cmd)

    body = (
        "<html><head><title>Log Viewer</title></head><body>"
        "<h1>Log Viewer</h1>"
        f"<pre>{output}</pre>"
        "</body></html>"
    )
    return 200, {"Content-Type": "text/html"}, body
